import events.models
from django.db import migrations, models
from django.utils import timezone


def fill_codes_and_form_status(apps, schema_editor):
    """Give every existing registration its own code.

    Registrations from before this change went through the old "Done" button
    of the form page, so they count as filled in according to the member.
    """
    db = schema_editor.connection.alias
    Registration = apps.get_model("events", "Registration")
    codes = set()
    for registration in Registration.objects.using(db).select_related("event"):
        code = events.models.make_registration_code()
        while code in codes:
            code = events.models.make_registration_code()
        codes.add(code)
        registration.code = code
        if registration.event.form_link:
            registration.form_status = "self_reported"
            registration.form_completed_at = timezone.now()
        registration.save(update_fields=["code", "form_status", "form_completed_at"])


